local function C_4()
	local script = LMG2L["LocalScript_4"];
	-- GUI LOGO ANIMASI	

	local player = game.Players.LocalPlayer	
	local gui = Instance.new("ScreenGui")	
	gui.Name = "LogoGUI"	
	gui.Parent = player:WaitForChild("PlayerGui")	

	-- Frame	
	local frame = Instance.new("Frame")	
	frame.Size = UDim2.new(0, 120, 0, 120)	
	frame.Position = UDim2.new(0.5, -60, 0.5, -60) -- mulai dari tengah	
	frame.BackgroundTransparency = 1	
	frame.Parent = gui	

	-- Logo	
	local logo = Instance.new("ImageLabel")	
	logo.Size = UDim2.new(1, 0, 1, 0)	
	logo.BackgroundTransparency = 1	
	logo.Image = "rbxassetid://93394912344294"	
	logo.Parent = frame	

	-- Tween (animasi)	
	local TweenService = game:GetService("TweenService")	

	local tweenInfo = TweenInfo.new(	
		1.5, -- durasi	
		Enum.EasingStyle.Quad,	
		Enum.EasingDirection.Out	
	)	

	local goal = {}	
	goal.Position = UDim2.new(1, -800, 1, -130) -- tujuan kanan bawah	

	local tween = TweenService:Create(frame, tweenInfo, goal)	

	-- Delay sedikit biar dramatis	
	task.wait(3)	
	tween:Play()	

	-- Opsional: bisa di drag setelah animasi	
	frame.Active = true	
	frame.Draggable = true	
end;
